SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, FIRST_VALUE(cost, TRUE) OVER w_ordered AS first_known_cost, LAST_VALUE(carrier) IGNORE NULLS OVER (PARTITION BY order_id, carrier ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date DESC, id) AS seq_no FROM shipments WINDOW w_ordered AS (PARTITION BY order_id, carrier ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
